import{_ as t,C as n,o as r,c as l,a2 as s,E as a}from"./chunks/framework.BSaF8iZ6.js";const _=JSON.parse('{"title":"Communications","description":"","frontmatter":{},"headers":[],"relativePath":"customers/communications.md","filePath":"customers/communications.md","lastUpdated":1789411447000}'),i={name:"customers/communications.md"};function m(c,e,u,g,d,h){const o=n("ImagePopup");return r(),l("div",null,[e[0]||(e[0]=s('<h1 id="communications" tabindex="-1">Communications <a class="header-anchor" href="#communications" aria-label="Permalink to &quot;Communications&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span><span class="role role--customer">Customer</span></div><p>Communications keeps conversations inside the marketplace. Sellers talk to the store admin, and customers talk to sellers. Each conversation is a thread of messages, with file attachments.</p><h2 id="seller-and-admin" tabindex="-1">Seller and admin <a class="header-anchor" href="#seller-and-admin" aria-label="Permalink to &quot;Seller and admin&quot;">​</a></h2><h3 id="message-the-admin" tabindex="-1">Message the admin <a class="header-anchor" href="#message-the-admin" aria-label="Permalink to &quot;Message the admin&quot;">​</a></h3><ol><li>In the Seller Panel, go to <strong>Communication &gt;&gt; Admin</strong>.</li><li>Type your message.</li><li>To add a file, click the attachment icon and choose a JPEG, PNG, PDF, DOC or DOCX file. The largest file you can send depends on your server&#39;s upload limit. You can send a file without a message.</li><li>Click the send icon.</li></ol>',6)),a(o,{src:"/images/communications/communication.png",alt:"A seller's conversation with the admin"}),e[1]||(e[1]=s('<ul><li>Use <strong>Search Message</strong> to find a message, or the history icon to show only the last 7, 15 or 30 days, the last 6 months, or <strong>All Messages</strong>.</li><li>A message can be up to 255 characters.</li><li>If the admin blocks you, the page shows <strong>You are blocked by admin</strong> and you can&#39;t send messages.</li></ul><p>No emails are sent for messages between sellers and the admin, so check this page for replies.</p><h3 id="message-sellers" tabindex="-1">Message sellers <a class="header-anchor" href="#message-sellers" aria-label="Permalink to &quot;Message sellers&quot;">​</a></h3><ol><li>In the admin panel, go to <strong>Marketplace &gt;&gt; Communications</strong>.</li><li>Click a seller in <strong>Sellers</strong>, or search for one. You can start a conversation with any seller.</li><li>Type your message, add a file if needed, and click the send icon.</li></ol>',4)),a(o,{src:"/images/communications/admin-communications.png",alt:"The admin's Communications page with the sellers list"}),e[2]||(e[2]=s('<p>Sellers with unread messages show a count. The menu at the top of a conversation has:</p><ul><li><strong>Block Seller</strong> or <strong>Unblock Seller</strong>, once the conversation has a message. While a seller is blocked, neither of you can send messages;</li><li><strong>Clear Chat History</strong> — deletes every message in the conversation;</li><li><strong>Exit</strong> — closes the conversation.</li></ul><h2 id="customers-and-sellers" tabindex="-1">Customers and sellers <a class="header-anchor" href="#customers-and-sellers" aria-label="Permalink to &quot;Customers and sellers&quot;">​</a></h2><h3 id="message-a-seller" tabindex="-1">Message a seller <a class="header-anchor" href="#message-a-seller" aria-label="Permalink to &quot;Message a seller&quot;">​</a></h3><ol><li>Sign in to your customer account and go to <strong>Communications</strong>.</li><li>In <strong>Search</strong>, type the seller&#39;s business name and click the seller.</li><li>Type your message, add a file if needed, and click the send icon.</li></ol>',5)),a(o,{src:"/images/communications/customer-communications.png",alt:"A customer's conversation with a seller"}),e[3]||(e[3]=s('<p>The seller receives a <strong>New message from …</strong> email and replies in the same conversation. If a seller blocks you, you&#39;ll see <strong>You have been blocked by this seller.</strong></p><p>To stop emails when a seller replies, click the menu next to <strong>Sellers</strong>, open <strong>Communication Settings</strong>, switch <strong>Receive email for seller messages</strong> off and click <strong>Save</strong>.</p><h3 id="reply-to-customers" tabindex="-1">Reply to customers <a class="header-anchor" href="#reply-to-customers" aria-label="Permalink to &quot;Reply to customers&quot;">​</a></h3><ol><li>In the Seller Panel, go to <strong>Communication &gt;&gt; Customers</strong>.</li><li>Click a customer in the list.</li><li>Type your reply and click the send icon.</li></ol>',4)),a(o,{src:"/images/communications/customer-communication.png",alt:"A seller's conversation with a customer"}),e[4]||(e[4]=s('<ul><li>The list shows customers who have written to you. You can&#39;t start a conversation with a customer.</li><li>The customer receives a <strong>New message from …</strong> email, unless they have turned emails off.</li><li>To stop a customer from messaging you, open the menu at the top of the conversation and click <strong>Block Customer</strong>. Neither of you can send messages until you click <strong>Unblock Customer</strong>.</li><li>To stop emails about customer messages, go to <strong>Settings &gt;&gt; General</strong>. See <a href="./../seller-panel/account-settings">Account Settings</a>.</li></ul><p>Unread messages from customers and the admin are counted under <strong>Buyer Messages</strong> on your <a href="./../seller-panel/dashboard">Dashboard</a>.</p><h2 id="subscription-plans" tabindex="-1">Subscription plans <a class="header-anchor" href="#subscription-plans" aria-label="Permalink to &quot;Subscription plans&quot;">​</a></h2><p>When the store uses subscription plans, customers can only message sellers whose plan includes <strong>Communication &gt;&gt; Customers</strong>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li>Team members need <strong>Communication</strong>, with <strong>Admin</strong> and <strong>Customers</strong> as needed.</li><li>Admins need <strong>Marketplace &gt;&gt; Communications</strong>.</li></ul>',6))])}const f=t(i,[["render",m]]);export{_ as __pageData,f as default};
